def test_alert_schema_contains_required_business_fields() -> None:
    """The output contract must include context, severity, and expected-status metadata for the dashboard."""
    alerts = run_pipeline(ROOT / "data")
    assert alerts
    alert = alerts[0]

    required = {
        "date",
        "anomaly_type",
        "severity",
        "confidence",
        "score",
        "expected_value",
        "actual_value",
        "delta",
        "context",
        "is_expected",
        "root_cause_hypotheses",
        "llm_summary",
        "related_metrics",
    }
    assert required.issubset(alert.keys())
    assert isinstance(alert["context"], dict)
    assert isinstance(alert["related_metrics"], list)
    assert isinstance(alert["is_expected"], bool)
